def shift_text(text, key):
    out = ""
    for ch in text:
        if ch.isalpha():
            base = ord("A") if ch.isupper() else ord("a")
            out += chr((ord(ch) - base + key) % 26 + base)
        else:
            out += ch          # spaces and punctuation stay as they are
    return out

if __name__ == "__main__":
    secret = shift_text("Meet me at the library at noon", 3)
    print("encrypted:", secret)
    print("decrypted:", shift_text(secret, -3))
